 const f=p.featured_image||{},url=f.file||p.featured_image_url;
 if(!url)return null;
 let parsed;try{parsed=new URL(url);}catch{return null;}
 if(parsed.protocol!=='https:'||!['www.nasa.gov','images-assets.nasa.gov'].includes(parsed.hostname)||! /\.(jpe?g|png)$/i.test(parsed.pathname))return null;
 parsed.search='';if(parsed.hostname==='www.nasa.gov')parsed.searchParams.set('w','1600');
 return{id:String(f.id||p.id),url:parsed.href,title:clean(p.title?.rendered||f.title),description:clean(f.caption||f.alt),released:p.date_gmt+'Z',source:p.link};
}).filter(Boolean);}
function status(text){$('status').textContent=text;$('status').hidden=!text;}
