 if(refreshing||Date.now()-lastAttempt<300000)return;
 refreshing=true;lastAttempt=Date.now();
 try{
  const gathered=[];
  for(let page=1;page<=30;page++){
   gathered.push(...normalize(await NASA_NATIVE.feed(page)));
   if(R.dedupe(gathered).length>=720)break;
  }
  const fresh=R.dedupe(gathered);
  if(fresh.length<400)throw new Error('NASA returned too few distinct images');
  photos=fresh;lastRefresh=Date.now();save('catalog',{photos,fetchedAt:lastRefresh});
