}
function markCurrent(){if(current){history[current.photo.id]=Date.now();save('history',history);}}
function prune(){const now=Date.now();history=Object.fromEntries(Object.entries(history).filter(([,t])=>Number.isFinite(t)&&now-t<R.HOUR));}
