  const job=tail.then(async()=>{
   await new Promise(r=>setTimeout(r,Math.max(0,130-(Date.now()-last))));last=Date.now();
   const result=await screenpunk.connections.read(alias,operation,parameters);
   if(result.state!=='fresh'&&result.state!=='stale'){
    if(result.retryAfterSeconds)await new Promise(r=>setTimeout(r,Math.min(result.retryAfterSeconds,60)*1000));
    throw new Error(result.code||'NASA unavailable');
   }
   return result;
  });tail=job.catch(()=>{});return job;
