  async feed(page){return (await read('nasa','feed',{per_page:'100',page:String(page),orderby:'date',order:'desc',_fields:'id,date_gmt,title,featured_image,featured_image_url,link'})).data;},
  async photo(raw){
   const url=new URL(raw);let match;
   if(url.origin==='https://www.nasa.gov'&&(match=/^\/wp-content\/uploads\/(\d{4})\/(\d{2})\/([A-Za-z0-9_][A-Za-z0-9_.~-]{0,255})$/.exec(url.pathname)))
    return (await read('nasa','photo',{year:match[1],month:match[2],filename:match[3],w:'1600'})).resourceURL;
   if(url.origin==='https://images-assets.nasa.gov'&&(match=/^\/image\/([A-Za-z0-9_][A-Za-z0-9_.~-]{0,255})\/([A-Za-z0-9_][A-Za-z0-9_.~-]{0,255})$/.exec(url.pathname)))
    return (await read('archive','photo',{asset:match[1],filename:match[2].replace(/~(?:orig|large)\./,'~medium.')})).resourceURL;
   throw new Error('Unsupported NASA image path');
  }
 };
})();

(function(root){
'use strict';
const HOUR=3600000, INTERVAL=10000, DAY=86400000;
function candidates(photos,history,now,current,failed={}) {
